-- #510: refined, global content for the social media agent.
-- 1. Six deeper content pillars (terroir, winemaking, wine history, region spotlight, tasting skills, service and cellaring).
-- 2. QUIZ becomes connoisseur level and CURIOUS_FACT asks for facts a wine lover does not know yet.
-- 3. HUMOR stops rotating (content_pillars.active comes from V83). Argentine wine days stay as they are.
INSERT INTO content_pillars (code, name_es, name_en, weight, brief, brief_en, sort_order) VALUES
('TERROIR', 'Terroir', 'Terroir', 2, 'Terroir: un factor del lugar explicado con precisión y un viñedo o una región real donde se aprecia: el tipo de suelo (pizarra, caliza, granito, arcilla, suelos volcánicos o aluviales), el clima y la continentalidad, la altitud, la exposición, la influencia del mar o de la niebla, las viñas viejas o el pie franco. Qué le hace a la vid, cómo cambia el vino en la copa y un ejemplo concreto con nombre (denominación, pago o paraje) y una cifra (metros, grados, milímetros de lluvia, edad de las viñas).',
 'Terroir: one site factor explained precisely, with a real vineyard or region where it shows: the soil type (slate, limestone, granite, clay, volcanic or alluvial soils), climate and continentality, altitude, aspect, the influence of the sea or of fog, old or ungrafted vines. What it does to the vine, how it changes the wine in the glass and one concrete, named example (appellation, single vineyard or site) with a figure (metres, degrees, millimetres of rain, vine age).', 10),
('WINEMAKING', 'Elaboración', 'Winemaking', 2, 'Elaboración: una técnica o decisión de bodega explicada de punta a punta: maceración carbónica, vinificación en ánfora o qvevri, crianza biológica bajo velo de flor, método tradicional y degüelle, crianza sobre lías y bâtonnage, uso de racimo entero, roble francés frente a americano, appassimento, podredumbre noble. Qué es, por qué se hace, qué cambia en el aroma, la textura y la guarda, y dónde es emblemática, con nombres y datos concretos.',
 'Winemaking: one cellar technique or decision explained end to end: carbonic maceration, amphora or qvevri winemaking, biological ageing under flor, the traditional method and disgorgement, lees ageing and bâtonnage, whole-bunch fermentation, French versus American oak, appassimento, noble rot. What it is, why it is done, what it changes in aroma, texture and ageing, and where it is emblematic, with names and concrete figures.', 11),
('HISTORY', 'Historia del vino', 'Wine history', 2, 'Historia del vino: un episodio o un personaje con fecha y lugar, y lo que dejó en el vino de hoy: los qvevri de Georgia de hace unos 8.000 años, el vino en Roma, los monjes cistercienses y los climats de Borgoña, la clasificación de Burdeos de 1855, la filoxera, el Juicio de París de 1976, la llegada de las cepas al Nuevo Mundo. Cuéntalo como un relato breve con un dato sorprendente y cierra con lo que esa historia explica hoy en la copa.',
 'Wine history: one episode or figure with a date and a place, and what it left in today''s wine: Georgia''s qvevri of about 8,000 years ago, wine in Rome, the Cistercian monks and the climats of Burgundy, the 1855 Bordeaux classification, phylloxera, the 1976 Judgement of Paris, the arrival of grape varieties in the New World. Tell it as a short story with one surprising fact and close with what that story explains in the glass today.', 12),
('REGION', 'Región en foco', 'Region spotlight', 2, 'Región en foco: una denominación o región vitivinícola del mundo explicada como lo haría un sommelier: dónde está, su clima y sus suelos, las cepas y los estilos que la definen, las reglas de su denominación (rendimientos, crianza mínima, categorías), un productor o un pago de referencia y qué buscar en una botella. Alterna regiones clásicas y emergentes de distintos países y de ambos hemisferios.',
 'Region spotlight: one wine appellation or region of the world explained the way a sommelier would: where it is, its climate and soils, the grapes and styles that define it, its appellation rules (yields, minimum ageing, categories), one reference producer or vineyard and what to look for in a bottle. Alternate classic and emerging regions from different countries and both hemispheres.', 13),
('TASTING', 'Técnica de cata', 'Tasting skills', 2, 'Técnica de cata: una habilidad concreta para catar mejor: leer el color y el ribete, distinguir aromas primarios, secundarios y terciarios, evaluar acidez, tanino, alcohol y cuerpo, medir la persistencia, reconocer defectos (TCA o gusto a corcho, oxidación, reducción, brettanomyces). Qué mirar, cómo hacerlo paso a paso y qué te dice del vino, con un ejemplo de vino o estilo donde se nota.',
 'Tasting skills: one concrete skill for tasting better: reading the colour and the rim, telling primary, secondary and tertiary aromas apart, judging acidity, tannin, alcohol and body, measuring length, recognising faults (TCA or cork taint, oxidation, reduction, brettanomyces). What to look at, how to do it step by step and what it tells you about the wine, with an example wine or style where it shows.', 14),
('SERVICE', 'Servicio y guarda', 'Service and cellaring', 1, 'Servicio y guarda: una decisión práctica con su fundamento: la temperatura de servicio por estilo (en grados), cuándo y por qué decantar, la forma de la copa, cuánto dura una botella abierta, las condiciones de guarda (temperatura, humedad, luz, posición) y el potencial de envejecimiento por estilo. Cada consejo explica la razón física o química y da cifras concretas.',
 'Service and cellaring: one practical decision and the reason behind it: serving temperature by style (in degrees), when and why to decant, the shape of the glass, how long an open bottle lasts, storage conditions (temperature, humidity, light, position) and ageing potential by style. Every tip explains the physical or chemical reason and gives concrete figures.', 15)
ON CONFLICT (code) DO NOTHING;

UPDATE content_pillars SET brief = 'Quiz de nivel conocedor: una pregunta que exige saber de vino y no de cultura general (una denominación y su cepa, una técnica y su efecto, la cifra de una regla de crianza, un suelo y su región), con cuatro opciones A, B, C y D verosímiles en los slides; la respuesta correcta y una explicación técnica breve en el último slide. La pregunta invita a responder en los comentarios antes de deslizar.',
    brief_en = 'A connoisseur-level quiz: a question that takes wine knowledge rather than general culture (an appellation and its grape, a technique and its effect, a figure from an ageing rule, a soil and its region), with four plausible options A, B, C and D across the slides; the correct answer and a short technical explanation on the last slide. The question invites readers to answer in the comments before swiping.'
WHERE code = 'QUIZ';

UPDATE content_pillars SET brief = 'Formato "N datos sobre X": entre 3 y 5 curiosidades verificables sobre un tema del vino (una cepa, una región, una técnica de elaboración, un hito histórico) que una persona aficionada probablemente no conozca. Cada dato lleva una cifra, una fecha, un lugar o un nombre concreto y, cuando hace falta, el término técnico explicado en pocas palabras; nada de generalidades ni de datos obvios.',
    brief_en = '"N facts about X": three to five verifiable curiosities about one wine topic (a grape, a region, a winemaking technique, a historical milestone) that a wine lover probably does not know yet. Each fact carries a figure, a date, a place or a specific name and, where needed, the technical term explained in a few words; no generalities and no obvious facts.'
WHERE code = 'CURIOUS_FACT';

UPDATE content_pillars SET active = FALSE WHERE code = 'HUMOR';
